INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist ein Fernabsatzvertrag dasselbe wie ein Kauf im Laden?', 2, '[{"text": "Nein", "correct": true, "because": "Fernkommunikation vs. physisch"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Abschlüsse"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt ein Fernabsatzvertrag?', 3, '[{"text": "Verbrauchergeschäfte über Distanz ermöglichen", "correct": true, "because": "E-Commerce"}, {"text": "Daten speichern", "correct": false, "because": "Nicht primär"}, {"text": "Netzwerke verbinden", "correct": false, "because": "Kein Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Mittel werden für Fernabsatzverträge genutzt?', 5, '[{"text": "Internet", "correct": true, "because": "Online-Shopping"}, {"text": "Telefon", "correct": true, "because": "Bestellhotline"}, {"text": "Papierformulare", "correct": false, "because": "Nicht Fernkommunikation"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Ein Fernabsatzvertrag nutzt Fernkommunikationsmittel. b) Er erfordert physische Anwesenheit.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Keine Präsenz nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei einem Fernabsatzvertrag?', 4, '[{"text": "Widerrufsrecht", "correct": false, "because": "Verbraucherschutz"}, {"text": "Fernkommunikation", "correct": false, "because": "Grundlage"}, {"text": "Papiergewicht", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Fernabsatzvertrag immer online ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Telefon, Fax"}, {"text": "Ja", "correct": false, "because": "Mehrere Mittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Recht hat der Verbraucher bei einem Fernabsatzvertrag?', 3, '[{"text": "Widerrufsrecht", "correct": true, "because": "14 Tage"}, {"text": "Kaufrecht", "correct": false, "because": "Kein Begriff"}, {"text": "Speicherrecht", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet ein Fernabsatzvertrag?', 5, '[{"text": "Flexibilität", "correct": true, "because": "Ortsunabhängig"}, {"text": "Widerrufsrecht", "correct": true, "because": "Verbraucherschutz"}, {"text": "Physische Prüfung", "correct": false, "because": "Nicht möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Fernabsatzverträge sind online möglich. b) Sie haben kein Widerrufsrecht. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Widerrufsrecht vorhanden"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für einen Fernabsatzvertrag?', 4, '[{"text": "Fernkommunikationsmittel", "correct": false, "because": "Grundlage"}, {"text": "Verbraucher", "correct": false, "because": "Vertragspartei"}, {"text": "Physische Anwesenheit", "correct": true, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Fernabsatzvertrag immer digital?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Telefon, Brief"}, {"text": "Ja", "correct": false, "because": "Verschiedene Mittel"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Beispiele sind Fernabsatzverträge?', 4, '[{"text": "Online-Shop-Kauf", "correct": true, "because": "Internet"}, {"text": "Telefonbestellung", "correct": true, "because": "Fernkommunikation"}, {"text": "Ladenkauf", "correct": false, "because": "Physisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Fernabsatzverträge keine Rückgabe erlauben. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "14 Tage Widerruf"}, {"text": "Ja", "correct": false, "because": "Widerrufsrecht"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei einem Fernabsatzvertrag?', 3, '[{"text": "Verbraucherschutz", "correct": true, "because": "Widerrufsrecht"}, {"text": "Papierformulare", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Rechte zählen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Fernabsatzverträge nutzen E-Mail. b) Sie erfordern persönlichen Kontakt.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kein Kontakt nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Pflichten hat der Unternehmer bei einem Fernabsatzvertrag?', 5, '[{"text": "Informationspflicht", "correct": true, "because": "Verbraucher informieren"}, {"text": "Widerrufsbelehrung", "correct": true, "because": "Rechte klären"}, {"text": "Physische Übergabe", "correct": false, "because": "Nicht erforderlich"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei einem Fernabsatzvertrag unwichtig?', 3, '[{"text": "Widerrufsrecht", "correct": false, "because": "Verbraucherschutz"}, {"text": "Fernkommunikation", "correct": false, "because": "Grundlage"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat ein Fernabsatzvertrag eine Widerrufsfrist?', 3, '[{"text": "Ja", "correct": true, "because": "14 Tage"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Fernabsatzvertrag physischen Kontakt ausschließt?', 2, '[{"text": "Ja", "correct": true, "because": "Nur Fernkommunikation"}, {"text": "Nein", "correct": false, "because": "Ausschließlich distanziert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für einen Fernabsatzvertrag zentral?', 4, '[{"text": "Fernkommunikationsmittel", "correct": true, "because": "Kernprinzip"}, {"text": "Physische Präsenz", "correct": false, "because": "Ausgeschlossen"}, {"text": "Papierdokumente", "correct": false, "because": "Sekundär"}]');
